package com.mediconnect.service;
import com.mediconnect.entity.*;import com.mediconnect.enums.*;import com.mediconnect.repository.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.util.*;
@Service public class AppointmentService{
 private final AppointmentRepository appointments;private final AvailabilityRepository availability;private final UserRepository users;
 public AppointmentService(AppointmentRepository a,AvailabilityRepository v,UserRepository u){appointments=a;availability=v;users=u;}
 @Transactional public Object book(User patient,UUID doctorId,UUID availabilityId){if(patient.getRole()!=UserRole.PATIENT)throw new AccessDeniedException("Only patients can book appointments.");User doctor=users.findById(doctorId).filter(u->u.getRole()==UserRole.DOCTOR&&u.getVerificationStatus()==VerificationStatus.APPROVED&&u.isActive()).orElseThrow(()->new IllegalArgumentException("Doctor is not available."));DoctorAvailability slot=availability.findById(availabilityId).orElseThrow(()->new IllegalArgumentException("This appointment slot is not available."));if(!slot.getDoctor().getId().equals(doctor.getId())||!slot.isAvailable()||slot.getDate().isBefore(LocalDate.now()))throw new IllegalArgumentException("This appointment slot is not available.");slot.setAvailable(false);try{appointments.flush();Appointment a=appointments.save(new Appointment(patient,doctor,slot));return view(a);}catch(DataIntegrityViolationException ex){throw new IllegalStateException("This appointment slot has already been booked.");}}
 @Transactional(readOnly=true) public List<?> mine(User user){List<Appointment> result=user.getRole()==UserRole.DOCTOR?appointments.findByDoctor_IdOrderByCreatedAtDesc(user.getId()):user.getRole()==UserRole.PATIENT?appointments.findByPatient_IdOrderByCreatedAtDesc(user.getId()):List.of();return result.stream().map(this::view).toList();}
 @Transactional public Object cancel(User user,UUID id){Appointment a=appointments.findById(id).orElseThrow(()->new IllegalArgumentException("Appointment not found."));if(!a.getPatient().getId().equals(user.getId())&&!a.getDoctor().getId().equals(user.getId())&&user.getRole()!=UserRole.ADMIN)throw new AccessDeniedException("You cannot manage this appointment.");if(a.getStatus()==AppointmentStatus.COMPLETED)throw new IllegalStateException("Completed appointments cannot be cancelled.");a.setStatus(AppointmentStatus.CANCELLED);a.getAvailability().setAvailable(true);return view(a);}
 @Transactional public Object updateStatus(User user,UUID id,AppointmentStatus status){Appointment a=appointments.findById(id).orElseThrow(()->new IllegalArgumentException("Appointment not found."));if(!a.getDoctor().getId().equals(user.getId())&&user.getRole()!=UserRole.ADMIN)throw new AccessDeniedException("You cannot manage this appointment.");a.setStatus(status);if(status==AppointmentStatus.CONFIRMED||status==AppointmentStatus.COMPLETED)a.getAvailability().setAvailable(false);return view(a);}
 private Map<String,Object> view(Appointment a){DoctorAvailability slot=a.getAvailability();Map<String,Object> m=new LinkedHashMap<>();m.put("id",a.getId().toString());m.put("patientName",a.getPatient().getName());m.put("doctorName",a.getDoctor().getName());m.put("appointmentDate",slot.getDate().toString());m.put("startTime",slot.getStartTime().toString());m.put("endTime",slot.getEndTime().toString());m.put("status",a.getStatus().name());return m;}
}
